{
  "type": "four-panel anime manga page",
  "style": "clean polished anime illustration, warm indoor lighting, highly legible vertical Japanese speech balloons, soft shading, expressive comic framing, detailed cozy living room background, light brown and beige interior, wood floor, sofa, coffee table, mugs, small plant, framed wall art",
  "format": {
    "page_orientation": "portrait",
    "panel_count": 4,
    "reading_flow": "top-left, top-right, middle-wide, bottom-wide",
    "borders": "thick black manga panel borders"
  },
  "characters": [
    {
      "id": "blue cat girl",
      "appearance": "small chibi catgirl with short bobbed {argument name="hair color" default="blue"} hair, ahoge, cat ears with white inner fur, fluffy tail with white tip, large amber-blue eyes, tiny fang-like mouth",
      "outfit": "orange sweater over a white collared shirt with blue trim, brown skirt with a ribbon belt, yellow X-shaped hair clip"
    },
    {
      "id": "golden cat girl",
      "appearance": "energetic catgirl with long wavy golden-blonde hair, cat ears, fluffy tail, bright cheerful expression",
      "outfit": "mustard yellow cable-knit sweater, dark brown plaid skirt"
    },
    {
      "id": "white-haired woman",
      "appearance": "beautiful woman with long white hair, white cat ears, dark tan skin, golden eyes, calm confident smile",
      "outfit": "white jacket over a black top, layered gold necklaces and earrings"
    },
    {
      "id": "maid woman",
      "appearance": "adult woman with long light blonde hair and cat ears",
      "outfit": "black-and-white maid dress with white frilled headpiece and a red ribbon bow"
    }
  ],
  "layout": {
    "sections": [
      {
        "title": "panel 1",
        "position": "top-left",
        "count": 1,
        "labels": ["どうせ日本語微妙なんでしょ？文字がダメなら認めないよ"],
        "scene": "the blue cat girl sits on a sofa in a cozy living room, one finger on her chin, looking skeptical and curious, a small question mark floating above her head"
      },
      {
        "title": "panel 2",
        "position": "top-right",
        "count": 1,
        "labels": ["ねぇねぇ！GPT Image2 すごいよ！"],
        "scene": "the golden cat girl bursts in dramatically through a doorway with speed lines radiating behind her, arms spread wide, full of excitement"
      },
      {
        "title": "panel 3",
        "position": "middle-wide",
        "count": 3,
        "labels": ["うわっ びっくりした！めちゃくちゃキレイじゃん！", "ねぇねぇ！GPT Image2 すごいよ！ 微妙なんでしょ？ 文字がダメなら認めないよ", "ほら見て！わたしたちのセリフ！"],
        "scene": "the blue cat girl reacts in shock with both hands near her face, the golden cat girl stands beside her and points proudly, and a large central speech balloon displays the example Japanese dialogue they are discussing"
      },
      {
        "title": "panel 4",
        "position": "bottom-wide",
        "count": 3,
        "labels": ["進化が早すぎてもう驚かないよね〜", "絵も可愛く描けてるし文字の白抜きも完璧よね", ""],
        "scene": "in the foreground, the maid woman covers her mouth in impressed amazement while the white-haired woman comments thoughtfully with a hand near her chin; in the background, the blue cat girl and golden cat girl jump happily together in celebration in front of the sofa"
      }
    ]
  },
  "text_handling": {
    "language": "Japanese",
    "balloon_direction": "vertical text layout",
    "emphasis": "make the Japanese typography crisp, natural, and cleanly integrated into manga speech balloons, including white knockout text where needed"
  },
  "tone": "playful, celebratory, impressed by high-quality Japanese text rendering in AI-generated manga",
  "quality": "high detail, cohesive character designs, cute and readable promotional comic"
}

{
  "type": "dark SaaS analytics dashboard UI",
  "product": {
    "brand": "{argument name=\"brand name\" default=\"AICode\"}",
    "theme": "dark navy blue glassmorphism interface with subtle gradients, soft glow, rounded cards, thin borders, modern developer-tool aesthetic"
  },
  "canvas": {
    "aspect_ratio": "16:9",
    "background": "deep midnight blue with faint vignette and soft radial lighting"
  },
  "layout": {
    "structure": "left sidebar plus main content area",
    "sections": [
      {
        "title": "Sidebar",
        "position": "left",
        "count": 8,
        "labels": ["AICode", "Overview", "Projects", "AI Assistants", "API & Usage", "Code Quality", "Team", "Settings"],
        "details": "logo at top, Overview selected with purple highlight, lower subscription card showing Pro Plan, renews in 12 days, horizontal progress bar at 75%, user profile at bottom with avatar, {argument name=\"user name\" default=\"Alex Morgan\"}, and email alex@morgan.dev"
      },
      {
        "title": "Header",
        "position": "top main area",
        "count": 4,
        "labels": ["Welcome back, Alex 👋", "Here's what's happening with your AI coding platform today.", "May 12 – Jun 12, 2024", "Export Report"],
        "details": "large greeting on left, date range picker and export button on right"
      },
      {
        "title": "Metric cards",
        "position": "top row under header",
        "count": 4,
        "labels": ["Total Users", "Active Projects", "API Calls", "Code Quality Score"],
        "values": ["12,842", "2,153", "1.28M", "876"],
        "details": "each card has a small colored icon, large main value, comparison text vs Apr 12 – May 12, 2024, positive change percentages 14.6%, 8.3%, 23.7%, 5.9%, and a miniature line chart at the bottom; colors are purple, green, amber, and blue"
      },
      {
        "title": "Main analytics panels",
        "position": "middle and bottom rows",
        "count": 4,
        "labels": ["API Calls Over Time", "Top Projects", "User Activity Heatmap", "Code Quality Trends"],
        "details": "API Calls Over Time is a wide area chart with Daily dropdown and rising purple line ending near 250K; Top Projects is a ranked list of 5 items with progress bars and percentage changes; User Activity Heatmap is a 7-row weekly heatmap with hour labels from 12 AM to 9 PM; Code Quality Trends is a line chart with Weekly dropdown and smooth upward purple trend from about 70 to low 90s"
      },
      {
        "title": "Top Projects list",
        "position": "middle right panel",
        "count": 5,
        "labels": ["AI Code Assistant", "Smart Refactor", "Code Review Bot", "Doc Generator", "Test Builder"],
        "values": ["485K", "321K", "214K", "132K", "98K"],
        "details": "green positive deltas for first four items 12.4%, 8.7%, 3.1%, 6.8%, and red negative delta -1.2% for Test Builder; each row has a colored square icon and thin horizontal progress bar"
      }
    ]
  },
  "style": {
    "visual_language": "premium fintech and AI product design mockup",
    "rendering": "crisp high-fidelity UI mockup, subtle shadows, neon edge lighting, polished charts, clean sans-serif typography",
    "primary_accent": "{argument name=\"accent color\" default=\"electric purple\"}",
    "secondary_accents": ["emerald green", "amber yellow", "cyan blue"],
    "density": "information-rich but spacious, balanced grid, highly legible"
  }
}

